PRAGMA foreign_keys = ON;
CREATE TABLE channels (channel_id TEXT NOT NULL PRIMARY KEY, name TEXT NOT NULL, channel_type TEXT NOT NULL CHECK (channel_type IN ('digital','offline')));
CREATE TABLE audiences (audience_id TEXT NOT NULL PRIMARY KEY, name TEXT NOT NULL, segment TEXT NOT NULL);
CREATE TABLE creatives (creative_id TEXT NOT NULL PRIMARY KEY, name TEXT NOT NULL, format TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE campaigns (campaign_id TEXT NOT NULL PRIMARY KEY, name TEXT NOT NULL, channel_id TEXT NOT NULL REFERENCES channels(channel_id), audience_id TEXT NOT NULL REFERENCES audiences(audience_id), creative_id TEXT NOT NULL REFERENCES creatives(creative_id), start_date TEXT NOT NULL, end_date TEXT NOT NULL, budget_amount NUMERIC NOT NULL CHECK (budget_amount >= 0), budget_currency TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('active','completed')), CHECK (start_date <= end_date));
CREATE TABLE campaign_events (campaign_event_id TEXT NOT NULL PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(campaign_id), event_type TEXT NOT NULL CHECK (event_type IN ('campaign_created','campaign_revised')), occurred_at TEXT NOT NULL, details_json TEXT NOT NULL);
CREATE TABLE contacts (contact_id TEXT NOT NULL PRIMARY KEY, created_date TEXT NOT NULL, region TEXT NOT NULL, consent_status TEXT NOT NULL CHECK (consent_status IN ('granted','withdrawn')), lifecycle_state TEXT NOT NULL CHECK (lifecycle_state IN ('prospect','customer')));
CREATE TABLE contact_audiences (contact_audience_id TEXT NOT NULL PRIMARY KEY, contact_id TEXT NOT NULL REFERENCES contacts(contact_id), audience_id TEXT NOT NULL REFERENCES audiences(audience_id), valid_from TEXT NOT NULL, valid_to TEXT, UNIQUE(contact_id,audience_id,valid_from), CHECK (valid_to IS NULL OR valid_from <= valid_to));
CREATE TABLE touchpoints (touchpoint_id TEXT NOT NULL PRIMARY KEY, contact_id TEXT NOT NULL REFERENCES contacts(contact_id), campaign_id TEXT NOT NULL REFERENCES campaigns(campaign_id), channel_id TEXT NOT NULL REFERENCES channels(channel_id), creative_id TEXT NOT NULL REFERENCES creatives(creative_id), occurred_at TEXT NOT NULL, touch_type TEXT NOT NULL CHECK (touch_type IN ('online','offline')), source TEXT NOT NULL);
CREATE TABLE web_sessions (session_id TEXT NOT NULL PRIMARY KEY, contact_id TEXT REFERENCES contacts(contact_id), touchpoint_id TEXT REFERENCES touchpoints(touchpoint_id), lead_id TEXT REFERENCES leads(lead_id) DEFERRABLE INITIALLY DEFERRED, opportunity_id TEXT REFERENCES opportunities(opportunity_id) DEFERRABLE INITIALLY DEFERRED, started_at TEXT NOT NULL, pages_viewed INTEGER NOT NULL CHECK (pages_viewed >= 0), session_type TEXT NOT NULL CHECK (session_type IN ('identified','anonymous')));
CREATE TABLE leads (lead_id TEXT NOT NULL PRIMARY KEY, contact_id TEXT NOT NULL REFERENCES contacts(contact_id), source_session_id TEXT NOT NULL UNIQUE REFERENCES web_sessions(session_id) DEFERRABLE INITIALLY DEFERRED, created_at TEXT NOT NULL, lead_score INTEGER NOT NULL CHECK (lead_score BETWEEN 0 AND 100), status TEXT NOT NULL CHECK (status IN ('new','qualified','converted','disqualified')));
CREATE TABLE lead_events (lead_event_id TEXT NOT NULL PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(lead_id), from_status TEXT, to_status TEXT NOT NULL, changed_at TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE opportunities (opportunity_id TEXT NOT NULL PRIMARY KEY, lead_id TEXT NOT NULL UNIQUE REFERENCES leads(lead_id), contact_id TEXT NOT NULL REFERENCES contacts(contact_id), created_at TEXT NOT NULL, closed_at TEXT, status TEXT NOT NULL CHECK (status IN ('closed_won','closed_lost','qualified')), estimated_amount NUMERIC NOT NULL CHECK (estimated_amount >= 0), currency TEXT NOT NULL);
CREATE TABLE opportunity_events (opportunity_event_id TEXT NOT NULL PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(opportunity_id), from_status TEXT, to_status TEXT NOT NULL, changed_at TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE orders (order_id TEXT NOT NULL PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(opportunity_id), ordered_at TEXT NOT NULL, revenue_amount NUMERIC NOT NULL CHECK (revenue_amount >= 0), currency TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE cost_records (cost_record_id TEXT NOT NULL PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(campaign_id), incurred_date TEXT NOT NULL, amount NUMERIC NOT NULL CHECK (amount >= 0), currency TEXT NOT NULL, cost_type TEXT NOT NULL);
CREATE TABLE attribution_results (attribution_result_id TEXT NOT NULL PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(opportunity_id), campaign_id TEXT NOT NULL REFERENCES campaigns(campaign_id), model TEXT NOT NULL CHECK (model IN ('first_touch','last_touch','linear')), credit_weight NUMERIC NOT NULL CHECK (credit_weight BETWEEN 0 AND 1), attributed_revenue NUMERIC NOT NULL CHECK (attributed_revenue >= 0), conversion_date TEXT NOT NULL, evaluation_period TEXT NOT NULL CHECK (evaluation_period IN ('train','validation','test')), rule_version TEXT NOT NULL, UNIQUE(opportunity_id,campaign_id,model));
CREATE TABLE campaign_metrics (campaign_metric_id TEXT NOT NULL PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(campaign_id), model TEXT NOT NULL CHECK (model IN ('first_touch','last_touch','linear')), evaluation_period TEXT NOT NULL CHECK (evaluation_period IN ('train','validation','test')), attributed_revenue NUMERIC NOT NULL, attributed_conversions NUMERIC NOT NULL, spend_base_currency NUMERIC, cost_status TEXT NOT NULL CHECK (cost_status IN ('available','missing','currency_mismatch')), roi NUMERIC, UNIQUE(campaign_id,model,evaluation_period));
CREATE INDEX idx_touchpoints_contact_time ON touchpoints(contact_id, occurred_at);
CREATE INDEX idx_opportunities_status_closed ON opportunities(status, closed_at);
CREATE INDEX idx_attribution_campaign_period ON attribution_results(campaign_id, model, evaluation_period);

BEGIN;
COMMIT;
